import sailpoint.object.TaskDefinition;
import sailpoint.object.TaskResult;
import sailpoint.api.TaskManager;
import java.util.HashMap;

String taskName = "Refresh MNB Attributes";
TaskDefinition td = context.getObjectByName(TaskDefinition.class, taskName);
if (td == null) return "FAIL missing " + taskName;
TaskResult tr = new TaskManager(context).runSync(td, new HashMap());
return "OK " + taskName + " " + tr.getCompletionStatus();
